class Shape {
    [int] Area() { throw 'Area is not implemented' }   # no abstract keyword
}

class Rectangle : Shape {
    [int] $Width
    [int] $Height
    Rectangle([int] $width, [int] $height) { $this.Width = $width; $this.Height = $height }
    [int] Area() { return $this.Width * $this.Height }
}

class Triangle : Shape {
    [int] $Base
    [int] $Height
    Triangle([int] $base, [int] $height) { $this.Base = $base; $this.Height = $height }
    [int] Area() { return $this.Base * $this.Height / 2 }
}

[Shape[]] $shapes = [Rectangle]::new(3, 4), [Triangle]::new(10, 3)
foreach ($shape in $shapes) {
    '{0}: {1}' -f $shape.GetType().Name, $shape.Area()
}

