# Commands pass .NET objects down the pipeline, not lines of text, so each stage
# filters, sorts and groups by property name, and Year stays an [int] throughout.
function Get-Shell {    # Verb-Noun, like every cmdlet; it emits six objects
    [pscustomobject]@{ Name = 'Thompson shell'; Year = 1971; Pipes = 'text' }
    [pscustomobject]@{ Name = 'Bourne shell';   Year = 1979; Pipes = 'text' }
    [pscustomobject]@{ Name = 'KornShell';      Year = 1983; Pipes = 'text' }
    [pscustomobject]@{ Name = 'Bash';           Year = 1989; Pipes = 'text' }
    [pscustomobject]@{ Name = 'PowerShell';     Year = 2006; Pipes = 'objects' }
    [pscustomobject]@{ Name = 'Nushell';        Year = 2019; Pipes = 'tables' }
}

Get-Shell | Where-Object Year -gt 1980 | Sort-Object Year -Descending |
    Select-Object -First 3 | ForEach-Object { '{0} ({1})' -f $_.Name, $_.Year }

Get-Shell | Group-Object Pipes | ForEach-Object {
    '{0,-7} {1}' -f $_.Name, ($_.Group.Name -join ', ')    # .Group holds the objects
}

$years = Get-Shell | Measure-Object Year -Minimum -Maximum
'{0} shells, {1} years apart' -f $years.Count, ($years.Maximum - $years.Minimum)
